<?php $title='Correo y notificaciones'; require __DIR__.'/partials/top.php'; $cfg=[];$profiles=[]; try{$st=appDb()->prepare('SELECT * FROM correo WHERE tenant_id=? AND is_default=1 ORDER BY correo_id DESC LIMIT 1');$st->execute([$_SESSION['user']['tenant_id']]);$cfg=$st->fetch()?:[];$all=appDb()->prepare('SELECT correo_id,nombre,metodo_envio,correo,graph_user,server,is_default,estado FROM correo WHERE tenant_id=? ORDER BY is_default DESC,correo_id DESC');$all->execute([$_SESSION['user']['tenant_id']]);$profiles=$all->fetchAll();}catch(Throwable $e){} $method=$cfg['metodo_envio']??'SMTP'; ?>
<section class="welcome"><div><small>COMUNICACIONES</small><h1>Correo y notificaciones</h1><p>Configura SMTP o Microsoft Graph. Si no lo configuras, ZYNKO funciona normalmente pero no enviará correos.</p></div></section>
<?php if(!empty($emailSettingsMessage)):?><section class="panel spaced"><b>✓ <?=htmlspecialchars($emailSettingsMessage)?></b></section><?php endif?><?php if(!empty($emailSettingsError)):?><section class="panel spaced"><b style="color:#a33">Error: <?=htmlspecialchars($emailSettingsError)?></b></section><?php endif?>
<section class="panel spaced"><div class="panel-head"><div><b>Proveedores configurados</b><small>Selecciona cuál usar. Puedes conservar Graph y SMTP configurados al mismo tiempo.</small></div></div><div class="mail-profile-grid"><?php if(!$profiles):?><div class="empty-compact"><i class="fa-solid fa-envelope-circle-check"></i><b>Sin proveedores guardados</b><span>Completa el formulario para crear el primero.</span></div><?php else:foreach($profiles as $mp):?><article class="mail-profile <?=$mp['is_default']?'active':''?>"><span class="mail-provider-icon"><i class="fa-solid <?=$mp['metodo_envio']==='GRAPH'?'fa-cloud':'fa-server'?>"></i></span><div><b><?=htmlspecialchars($mp['metodo_envio']==='GRAPH'?'Microsoft Graph':'SMTP')?></b><small><?=htmlspecialchars($mp['metodo_envio']==='GRAPH'?($mp['graph_user']?:'Sin buzón'):($mp['correo']?:$mp['server']))?></small></div><span class="status <?=$mp['is_default']?'ok':''?>"><?=$mp['is_default']?'En uso':'Disponible'?></span><div class="mail-profile-actions"><?php if(!$mp['is_default']):?><button class="soft email-activate" data-id="<?=$mp['correo_id']?>"><i class="fa-solid fa-circle-check"></i> Usar / editar</button><button class="soft danger email-delete" data-id="<?=$mp['correo_id']?>"><i class="fa-solid fa-trash"></i></button><?php else:?><button class="soft" type="button" onclick="document.getElementById('mailMethod').scrollIntoView({behavior:'smooth',block:'center'})"><i class="fa-solid fa-pen"></i> Editar</button><?php endif?></div></article><?php endforeach;endif?></div></section>
<form method="post"><input type="hidden" name="action" value="email_save"><section class="panel spaced"><div class="panel-head"><div><b>Proveedor de envío</b><small>Las credenciales sensibles se guardan cifradas. Deja una contraseña/secret vacío para conservar el existente.</small></div></div><div class="settings-grid"><div class="field"><label>Método de envío</label><select class="select2" id="mailMethod" name="method"><option value="SMTP" <?=$method==='SMTP'?'selected':''?>>SMTP</option><option value="GRAPH" <?=$method==='GRAPH'?'selected':''?>>Microsoft Graph</option></select></div><div class="field smtp-fields"><label>Correo emisor SMTP</label><input name="sender" type="email" value="<?=htmlspecialchars($cfg['correo']??'')?>"></div></div><div class="mail-fields smtp-fields settings-grid"><div class="field"><label>Servidor SMTP</label><input name="server" value="<?=htmlspecialchars($cfg['server']??'')?>" placeholder="smtp.office365.com"></div><div class="field"><label>Puerto</label><input name="port" value="<?=htmlspecialchars($cfg['port']??'587')?>" inputmode="numeric"></div><div class="field"><label>Seguridad</label><select class="select2" name="smtp_secure"><option value="tls" <?=($cfg['smtp_secure']??'tls')==='tls'?'selected':''?>>TLS</option><option value="ssl" <?=($cfg['smtp_secure']??'')==='ssl'?'selected':''?>>SSL</option></select></div><div class="field"><label>Contraseña / App password</label><input name="smtp_password" type="password" autocomplete="new-password" placeholder="<?=empty($cfg['password'])?'Obligatoria':'•••••••• (conservar si queda vacío)'?>"></div></div><div class="mail-fields graph-fields settings-grid" hidden><div class="field"><label>Tenant ID</label><input name="graph_tenant" value="<?=htmlspecialchars($cfg['tenant_graph_id']??'')?>"></div><div class="field"><label>Client ID</label><input name="client_id" value="<?=htmlspecialchars($cfg['client_id']??'')?>"></div><div class="field"><label>Buzón de Microsoft Graph (Graph User / correo emisor)</label><input name="graph_user" type="email" value="<?=htmlspecialchars($cfg['graph_user']??'')?>"></div><div class="field"><label>Guardar en enviados</label><label class="switch-line"><input name="save_to_sent" type="checkbox" <?=($cfg['save_to_sent_items']??1)?'checked':''?>><span></span>Activado</label></div><div class="field full"><label>Client Secret</label><input name="client_secret" type="password" autocomplete="new-password" placeholder="<?=empty($cfg['client_secret'])?'Obligatorio':'•••••••• (conservar si queda vacío)'?>"></div></div><div class="settings-grid"><div class="field"><label>Destino interno predeterminado</label><input name="recipient" type="email" value="<?=htmlspecialchars($cfg['destinatario']??'')?>" placeholder="Opcional"></div><div class="field"><label>Copia oculta (BCC)</label><input name="bcc" value="<?=htmlspecialchars($cfg['copia']??'')?>" placeholder="correo1@dominio.com; correo2@dominio.com"></div></div><div class="actions-inline"><button class="primary" type="submit"><i class="fa-solid fa-floppy-disk"></i> Guardar configuración</button><span class="hint">Puedes cambiarla en cualquier momento.</span></div></section></form>
<section class="panel spaced"><div class="panel-head"><div><b>Estado</b><small><?=empty($cfg)?'Correo no configurado: no se enviarán emails hasta guardar un proveedor.':'Proveedor guardado: '.htmlspecialchars($method).'.'?></small></div></div></section>
<script>document.addEventListener('DOMContentLoaded',()=>{const m=document.getElementById('mailMethod'),ss=[...document.querySelectorAll('.smtp-fields')],gs=[...document.querySelectorAll('.graph-fields')];const sync=()=>{const graph=m.value==='GRAPH';ss.forEach(s=>{s.hidden=graph;s.querySelectorAll('input,select').forEach(e=>e.disabled=graph)});gs.forEach(g=>{g.hidden=!graph;g.querySelectorAll('input,select').forEach(e=>e.disabled=!graph)});};m.addEventListener('change',sync);sync();});</script>
<?php require __DIR__.'/partials/bottom.php'; ?>
